export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let stepCount = 0;
  let kt = 20.0; // effective (maxThrustSum / mass)
  let uf = 0.48; // filtered thrust command
  let prevVx = 0, prevVz = 0, prevVy = 0;
  let prevAxModel = 0, prevAzModel = 0, prevAyModel = 0;
  let wxAcc = 0, wzAcc = 0;
  let intZ = 0, intX = 0, intY = 0;
  let rollBias = 0, pitchBias = 0, yawInt = 0;
  let expRoll = 0, expRollRate = 0;
  let expPitch = 0, expPitchRate = 0;
  let lastThrust = 0.48, lastRoll = 0, lastPitch = 0;
  let gatePhase = 'stage';
  let currentGate = 0;
  let alignedCount = 0;
  let touchdownLock = false;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = cp * cr;
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (stepCount > 0) {
        uf += (lastThrust - uf) * (1 - Math.exp(-dt / 0.038));

        // Expected attitude tracking to identify weak-motor torque bias
        const rAcc = 65 * (lastRoll - expRoll) - 14 * expRollRate;
        expRollRate += rAcc * dt;
        expRoll += expRollRate * dt;
        const pAcc = 65 * (lastPitch - expPitch) - 14 * expPitchRate;
        expPitchRate += pAcc * dt;
        expPitch += expPitchRate * dt;

        if (p.y > 0.08 && p.y < 2.90) {
          rollBias = clamp(rollBias + 2.2 * (expRoll - att.roll) * dt, -0.28, 0.28);
          pitchBias = clamp(pitchBias + 2.2 * (expPitch - att.pitch) * dt, -0.28, 0.28);

          // Estimate vertical thrust gain kt
          const ayMeas = (v.y - prevVy) / dt;
          const cDrag = 0.54;
          const ayPred = kt * uf * dirY - 9.81 - cDrag * prevVy;
          const ayErr = clamp(ayMeas - ayPred, -8, 8);
          if (uf * dirY > 0.25) {
            kt = clamp(kt + 0.045 * ayErr / Math.max(0.3, uf * dirY), 14.5, 27.5);
          }

          // Disturbance observer for horizontal wind acceleration
          const axMeas = (v.x - prevVx) / dt;
          const azMeas = (v.z - prevVz) / dt;
          const wxInst = clamp(axMeas - prevAxModel, -12, 12);
          const wzInst = clamp(azMeas - prevAzModel, -12, 12);
          const alphaW = 0.22;
          wxAcc = clamp(wxAcc + alphaW * (wxInst - wxAcc), -10, 10);
          wzAcc = clamp(wzAcc + alphaW * (wzInst - wzAcc), -10, 10);
        } else {
          expRoll = att.roll; expRollRate = rates.roll;
          expPitch = att.pitch; expPitchRate = rates.pitch;
        }
      } else {
        expRoll = att.roll; expPitch = att.pitch;
      }

      const cDrag = 0.42 * (kt / 15.3);
      prevAxModel = kt * uf * dirX - cDrag * v.x;
      prevAzModel = kt * uf * dirZ - cDrag * v.z;
      prevAyModel = kt * uf * dirY - 9.81 - cDrag * v.y;
      prevVx = v.x; prevVz = v.z; prevVy = v.y;
      stepCount++;

      // Navigation logic
      let tx, ty, tz;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 6.5, kdX = 4.2;
      let kpZ = 9.0, kdZ = 5.2;
      let kpY = 8.0, kdY = 4.8;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (currentGate !== obs.gateIndex) {
          currentGate = obs.gateIndex;
          gatePhase = 'stage';
          alignedCount = 0;
          intZ = 0; intX = 0;
        }

        ty = g.y;
        tz = g.z;

        const ez = Math.abs(g.z - p.z);
        const ey = Math.abs(g.y - p.y);
        const ezPred = Math.abs(g.z - (p.z + v.z * 0.09));
        const eyPred = Math.abs(g.y - (p.y + v.y * 0.09));

        const zAligned = ez < 0.019 && ezPred < 0.022 && Math.abs(v.z) < 0.14;
        const yAligned = ey < 0.075 && eyPred < 0.09 && Math.abs(v.y) < 0.30;

        if (gatePhase === 'stage') {
          const stageDist = 0.28;
          tx = g.x - stageDist;
          if (zAligned && yAligned && p.x > g.x - 0.42 && p.x < g.x) {
            alignedCount++;
          } else {
            alignedCount = Math.max(0, alignedCount - 1);
          }
          if (alignedCount >= 4) {
            gatePhase = 'cross';
          }
        }

        if (gatePhase === 'cross') {
          // Check predicted clearance at gate crossing
          const dx = g.x - p.x;
          const tGo = clamp(dx / Math.max(0.25, v.x), 0.02, 0.25);
          const azCur = prevAzModel + wzAcc;
          const ayCur = prevAyModel;
          const zCross = p.z + v.z * tGo + 0.5 * clamp(azCur, -4, 4) * tGo * tGo;
          const yCross = p.y + v.y * tGo + 0.5 * clamp(ayCur, -4, 4) * tGo * tGo;

          if (dx > 0.05 && (Math.abs(zCross - g.z) > 0.026 || Math.abs(yCross - g.y) > 0.11 || ez > 0.026 || ey > 0.11)) {
            // Abort crossing and re-stage before hitting frame
            gatePhase = 'stage';
            alignedCount = 0;
            tx = g.x - 0.26;
            vxRef = 0;
          } else {
            tx = g.x + 0.30;
            vxRef = 0.95;
            kpZ = 12.0; kdZ = 6.0;
          }
        }
      } else {
        // Landing phase
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const distPad = Math.hypot(tx - p.x, tz - p.z);
        const speedHoriz = Math.hypot(v.x, v.z);

        if (touchdownLock) {
          if (distPad > 0.135) touchdownLock = false;
        } else if (distPad < 0.09 && p.y <= 0.11 && speedHoriz < 0.32 && Math.abs(v.y) < 0.35) {
          touchdownLock = true;
        }

        if (touchdownLock) {
          lastThrust = 0.06;
          lastRoll = 0;
          lastPitch = 0;
          return { thrust: 0.06, roll: 0, pitch: 0, yawRate: clamp(-4.0 * att.yaw, -2, 2) };
        }

        if (distPad > 0.35) {
          ty = Math.max(0.55, Math.min(1.05, p.y));
        } else if (distPad > 0.12) {
          ty = 0.22;
        } else {
          ty = 0.06;
          vyRef = p.y > 0.14 ? -0.35 : -0.15;
          kpX = 8.5; kdX = 5.0;
          kpZ = 8.5; kdZ = 5.0;
        }
      }

      // Position error & velocity shaping
      const ex = tx - p.x;
      const ez = tz - p.z;
      const ey = ty - p.y;

      if (Math.abs(ex) < 0.25) intX = clamp(intX + ex * dt, -0.25, 0.25);
      else intX *= 0.95;
      if (Math.abs(ez) < 0.25) intZ = clamp(intZ + ez * dt, -0.25, 0.25);
      else intZ *= 0.95;
      if (Math.abs(ey) < 0.30) intY = clamp(intY + ey * dt, -0.35, 0.35);
      else intY *= 0.95;

      // Clamp desired velocity to avoid aggressive overshoot
      const vxDes = clamp(vxRef + (kpX / kdX) * ex, -1.8, 1.8);
      const vzDes = clamp(vzRef + (kpZ / kdZ) * ez, -1.8, 1.8);
      const vyDes = clamp(vyRef + (kpY / kdY) * ey, -1.5, 1.6);

      // Desired accelerations including wind disturbance & drag cancellation
      const axDes = clamp(kdX * (vxDes - v.x) + 1.8 * intX - wxAcc + cDrag * v.x, -6.2, 6.2);
      const azDes = clamp(kdZ * (vzDes - v.z) + 2.5 * intZ - wzAcc + cDrag * v.z, -6.2, 6.2);
      const ayDes = clamp(kdY * (vyDes - v.y) + 2.2 * intY + cDrag * v.y, -4.5, 5.5);

      const totalAy = Math.max(2.0, 9.81 + ayDes);

      // Rotate desired horizontal acceleration into body frame
      const axBody = cy * axDes - sy * azDes;
      const azBody = sy * axDes + cy * azDes;

      // Exact nonlinear inverse of direction vector:
      // dirX_body = sin(pitch)*cos(roll), dirZ_body = -sin(roll), dirY = cos(pitch)*cos(roll)
      // axBody / totalAy = tan(pitch)
      // azBody / hypot(totalAy, axBody) = -tan(roll)
      const pitchTarget = Math.atan2(axBody, totalAy);
      const rollTarget = -Math.atan2(azBody, Math.hypot(totalAy, axBody));

      const pitch = clamp(pitchTarget + pitchBias - 0.06 * rates.pitch, -0.6, 0.6);
      const roll = clamp(rollTarget + rollBias - 0.06 * rates.roll, -0.6, 0.6);
      const thrust = clamp(totalAy / (kt * Math.max(0.55, dirY)), 0.05, 1.0);

      yawInt = clamp(yawInt - 5.0 * att.yaw * dt, -1.2, 1.2);
      const yawRate = clamp(-4.5 * att.yaw - 0.35 * rates.yaw + yawInt, -2, 2);

      lastThrust = thrust;
      lastRoll = roll;
      lastPitch = pitch;

      return { thrust, roll, pitch, yawRate };
    },
  };
}

