      const curAzThrust = kt * uf * dirZ - cDrag * v.z;
      const curAyThrust = kt * uf * dirY - 9.81 - cDrag * v.y;

      if (stepCount > 0 && p.y > 0.08 && p.y < 2.90) {
        // Estimate vertical thrust scale kt
        const ayMeas = (v.y - prevVy) / dt;
        const ayPred = 0.5 * (prevAyThrust + curAyThrust);
        const ayErr = clamp(ayMeas - ayPred, -8, 8);
        if (uf * dirY > 0.25) {
          kt = clamp(kt + 0.05 * ayErr / Math.max(0.3, uf * dirY), 14.5, 27.5);
        }

        // Estimate wind acceleration (Stage 2 disturbance)
        const axMeas = (v.x - prevVx) / dt;
        const azMeas = (v.z - prevVz) / dt;
        const wxInst = clamp(axMeas - 0.5 * (prevAxThrust + curAxThrust), -14, 14);
        const wzInst = clamp(azMeas - 0.5 * (prevAzThrust + curAzThrust), -14, 14);
        const alphaW = 0.24;
        wxAcc = clamp(wxAcc + alphaW * (wxInst - wxAcc), -10, 10);
        wzAcc = clamp(wzAcc + alphaW * (wzInst - wzAcc), -10, 10);

        // Estimate inner-loop attitude trim (Stage 1 weak-motor compensation)
        // Note: rollRef tracks lastRollDes (WITHOUT rollTrim), so when att.roll == rollRef, error is 0!
        rollTrim = clamp(rollTrim + 1.5 * (rollRef - att.roll) * dt, -0.22, 0.22);
        pitchTrim = clamp(pitchTrim + 1.5 * (pitchRef - att.pitch) * dt, -0.22, 0.22);
      }

      prevAxThrust = kt * uf * dirX - cDrag * v.x;
      prevAzThrust = kt * uf * dirZ - cDrag * v.z;
      prevAyThrust = kt * uf * dirY - 9.81 - cDrag * v.y;
      prevVx = v.x; prevVz = v.z; prevVy = v.y;
      stepCount++;

      let tx, ty, tz;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 6.5, kdX = 4.2;
      let kpZ = 9.5, kdZ = 5.4;
      let kpY = 8.0, kdY = 4.8;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (currentGate !== obs.gateIndex) {
          currentGate = obs.gateIndex;
          gatePhase = 'stage';
          alignedCount = 0;
          intZ = 0; intX = 0;
        }

        ty = g.y;
        tz = g.z;

        const ez = Math.abs(g.z - p.z);
        const ey = Math.abs(g.y - p.y);
        const ezPred = Math.abs(g.z - (p.z + v.z * 0.08));
        const eyPred = Math.abs(g.y - (p.y + v.y * 0.08));

        const zAligned = ez < 0.020 && ezPred < 0.023 && Math.abs(v.z) < 0.16;
        const yAligned = ey < 0.080 && eyPred < 0.095 && Math.abs(v.y) < 0.35;

        if (gatePhase === 'stage') {
          const stageDist = 0.26;
          tx = g.x - stageDist;
          if (zAligned && yAligned && p.x > g.x - 0.45 && p.x < g.x) {
            alignedCount++;
          } else {
            alignedCount = Math.max(0, alignedCount - 1);
          }
          if (alignedCount >= 3) {
            gatePhase = 'cross';
          }
        }

        if (gatePhase === 'cross') {
          const dx = g.x - p.x;
          const tGo = clamp(dx / Math.max(0.30, v.x), 0.02, 0.20);
          const azCur = prevAzThrust + wzAcc;
          const ayCur = prevAyThrust;
          const zCross = p.z + v.z * tGo + 0.5 * clamp(azCur, -4, 4) * tGo * tGo;
          const yCross = p.y + v.y * tGo + 0.5 * clamp(ayCur, -4, 4) * tGo * tGo;

          if (dx > 0.05 && (Math.abs(zCross - g.z) > 0.028 || Math.abs(yCross - g.y) > 0.115 || ez > 0.027 || ey > 0.115)) {
            gatePhase = 'stage';
            alignedCount = 0;
            tx = g.x - 0.24;
            vxRef = 0;
          } else {
            tx = g.x + 0.32;
            vxRef = 1.1;
            kpZ = 12.0; kdZ = 6.0;
          }
        }
      } else {
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const distPad = Math.hypot(tx - p.x, tz - p.z);
        const speedHoriz = Math.hypot(v.x, v.z);

        if (touchdownLock) {
          if (distPad > 0.135) touchdownLock = false;
        } else if (distPad < 0.095 && p.y <= 0.11 && speedHoriz < 0.35 && Math.abs(v.y) < 0.38) {
          touchdownLock = true;
        }

        if (touchdownLock) {
          lastThrust = 0.06;
          lastRollDes = 0;
          lastPitchDes = 0;
          return { thrust: 0.06, roll: 0, pitch: 0, yawRate: clamp(-4.0 * att.yaw, -2, 2) };
        }

        if (distPad > 0.35) {
          ty = Math.max(0.55, Math.min(1.05, p.y));
        } else if (distPad > 0.12) {
          ty = 0.22;
        } else {
          ty = 0.06;
          vyRef = p.y > 0.14 ? -0.35 : -0.15;
          kpX = 8.5; kdX = 5.0;
          kpZ = 8.5; kdZ = 5.0;
        }
      }

      const ex = tx - p.x;
      const ez = tz - p.z;
      const ey = ty - p.y;

      if (Math.abs(ex) < 0.30) intX = clamp(intX + ex * dt, -0.40, 0.40);
      else intX *= 0.95;
      if (Math.abs(ez) < 0.30) intZ = clamp(intZ + ez * dt, -0.40, 0.40);
      else intZ *= 0.95;
      if (Math.abs(ey) < 0.35) intY = clamp(intY + ey * dt, -0.40, 0.40);
      else intY *= 0.95;

      const vxDes = clamp(vxRef + (kpX / kdX) * ex, -1.8, 1.8);
      const vzDes = clamp(vzRef + (kpZ / kdZ) * ez, -1.8, 1.8);
      const vyDes = clamp(vyRef + (kpY / kdY) * ey, -1.5, 1.6);

      const axDes = clamp(kdX * (vxDes - v.x) + 2.5 * intX - wxAcc + cDrag * v.x, -6.2, 6.2);
      const azDes = clamp(kdZ * (vzDes - v.z) + 3.0 * intZ - wzAcc + cDrag * v.z, -6.2, 6.2);
      const ayDes = clamp(kdY * (vyDes - v.y) + 2.5 * intY + cDrag * v.y, -4.5, 5.5);

      const totalAy = Math.max(2.0, 9.81 + ayDes);

      const axBody = cy * axDes - sy * azDes;
      const azBody = sy * axDes + cy * azDes;

      const pitchDes = Math.atan2(axBody, totalAy);
      const rollDes = -Math.atan2(azBody, Math.hypot(totalAy, axBody));

      const pitch = clamp(pitchDes + pitchTrim + 0.4 * (pitchRef - att.pitch) - 0.06 * rates.pitch, -0.6, 0.6);
      const roll = clamp(rollDes + rollTrim + 0.4 * (rollRef - att.roll) - 0.06 * rates.roll, -0.6, 0.6);
      const thrust = clamp(totalAy / (kt * Math.max(0.55, dirY)), 0.05, 1.0);

      yawInt = clamp(yawInt - 5.0 * att.yaw * dt, -1.2, 1.2);
      const yawRate = clamp(-4.5 * att.yaw - 0.35 * rates.yaw + yawInt, -2, 2);

      lastThrust = thrust;
      lastRollDes = rollDes;
      lastPitchDes = pitchDes;

      return { thrust, roll, pitch, yawRate };
    },
  };
}

