export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let stepCount = 0;
  let kt = 19.8;
  let uf = 0.50;
  let prevVx = 0, prevVz = 0, prevVy = 0;
  let prevAxThrust = 0, prevAzThrust = 0, prevAyThrust = 0;
  let wxAcc = 0, wzAcc = 0;
  let wxBase = 0, wzBase = 0;
  let intZ = 0, intX = 0;
  let rollTrim = 0, pitchTrim = 0, yawInt = 0;
  let rollRef = 0, pitchRef = 0;
  let lastThrust = 0.50, lastRollDes = 0, lastPitchDes = 0;
  let gatePhase = 'stage';
  let currentGate = 0;
  let alignedCount = 0;
  let touchdownLock = false;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = cp * cr;
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (stepCount > 0) {
        uf += (lastThrust - uf) * (1 - Math.exp(-dt / 0.038));
        rollRef += (lastRollDes - rollRef) * (1 - Math.exp(-dt / 0.075));
        pitchRef += (lastPitchDes - pitchRef) * (1 - Math.exp(-dt / 0.075));
      } else {
        rollRef = att.roll;
        pitchRef = att.pitch;
      }

      const cDrag = 0.42 * (kt / 15.3);
      const curAxThrust = kt * uf * dirX - cDrag * v.x;
      const curAzThrust = kt * uf * dirZ - cDrag * v.z;
      const curAyThrust = kt * uf * dirY - 9.81 - cDrag * v.y;

      if (stepCount > 0 && p.y > 0.08 && p.y < 2.90) {
        const ayMeas = (v.y - prevVy) / dt;
        const ayPred = 0.5 * (prevAyThrust + curAyThrust);
        const ayErr = clamp(ayMeas - ayPred, -10, 10);
        if (uf * dirY > 0.22) {
          kt = clamp(kt + 0.08 * ayErr / Math.max(0.28, uf * dirY), 14.5, 27.5);
        }

        const axMeas = (v.x - prevVx) / dt;
        const azMeas = (v.z - prevVz) / dt;
        const wxInst = clamp(axMeas - 0.5 * (prevAxThrust + curAxThrust), -15, 15);
        const wzInst = clamp(azMeas - 0.5 * (prevAzThrust + curAzThrust), -15, 15);
        const alphaW = 0.26;
        wxAcc = clamp(wxAcc + alphaW * (wxInst - wxAcc), -11, 11);
        wzAcc = clamp(wzAcc + alphaW * (wzInst - wzAcc), -11, 11);

        // Before t = 1.95s there are no gusts; learn baseWind accurately
        if (obs.t > 0.25 && obs.t < 1.95) {
          wxBase += 0.05 * (wxAcc - wxBase);
          wzBase += 0.05 * (wzAcc - wzBase);
        }

        rollTrim = clamp(rollTrim + 3.2 * (rollRef - att.roll) * dt, -0.35, 0.35);
        pitchTrim = clamp(pitchTrim + 3.2 * (pitchRef - att.pitch) * dt, -0.35, 0.35);
      }

      prevAxThrust = kt * uf * dirX - cDrag * v.x;
      prevAzThrust = kt * uf * dirZ - cDrag * v.z;
      prevAyThrust = kt * uf * dirY - 9.81 - cDrag * v.y;
      prevVx = v.x; prevVz = v.z; prevVy = v.y;
      stepCount++;

      let tx, ty, tz;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 7.0, kdX = 4.5;
      let kpZ = 11.0, kdZ = 5.8;
      let kpY = 8.5, kdY = 5.0;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (currentGate !== obs.gateIndex) {
          currentGate = obs.gateIndex;
          gatePhase = 'stage';
          alignedCount = 0;
          intZ = 0; intX = 0;
        }

        ty = g.y;
        tz = g.z;

        const ez = Math.abs(g.z - p.z);
        const ey = Math.abs(g.y - p.y);
        const ezPred = Math.abs(g.z - (p.z + v.z * 0.07));
        const eyPred = Math.abs(g.y - (p.y + v.y * 0.07));

        const zAligned = ez < 0.021 && ezPred < 0.024 && Math.abs(v.z) < 0.18;
        const yAligned = ey < 0.085 && eyPred < 0.10 && Math.abs(v.y) < 0.38;

        if (gatePhase === 'stage') {
          const stageDist = 0.22;
          tx = g.x - stageDist;
          if (zAligned && yAligned && p.x > g.x - 0.42 && p.x < g.x) {
            alignedCount++;
          } else {
            alignedCount = Math.max(0, alignedCount - 1);
          }
          if (alignedCount >= 3) {
            gatePhase = 'cross';
          }
        }

        if (gatePhase === 'cross') {
          const dx = g.x - p.x;
          // Only abort if we are still far enough before the gate to stop safely
          // and predicted position at gate plane is outside safe keyhole
          const tGo = clamp(dx / Math.max(0.35, v.x), 0.02, 0.16);
          const zCross = p.z + v.z * tGo;
          const yCross = p.y + v.y * tGo;
          const canStop = dx > 0.13 && (p.x + v.x * 0.11 < g.x - 0.02);

          if (canStop && (Math.abs(zCross - g.z) > 0.029 || Math.abs(yCross - g.y) > 0.115 || ez > 0.029 || ey > 0.115)) {
            gatePhase = 'stage';
            alignedCount = 0;
            tx = g.x - 0.22;
            vxRef = 0;
          } else {
            tx = g.x + 0.35;
            vxRef = 1.15;
            kpZ = 13.5; kdZ = 6.4;
          }
        }
      } else {
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const distPad = Math.hypot(tx - p.x, tz - p.z);
        const speedHoriz = Math.hypot(v.x, v.z);

        if (touchdownLock) {
          if (distPad > 0.135) touchdownLock = false;
        } else if (distPad < 0.105 && p.y <= 0.115 && speedHoriz < 0.38 && Math.abs(v.y) < 0.40) {
          touchdownLock = true;
        }

        if (touchdownLock) {
          lastThrust = 0.06;
          lastRollDes = 0;
          lastPitchDes = 0;
          return { thrust: 0.06, roll: 0, pitch: 0, yawRate: clamp(-4.0 * att.yaw, -2, 2) };
        }

        if (distPad > 0.35) {
          ty = Math.max(0.50, Math.min(1.00, p.y));
        } else if (distPad > 0.13) {
          ty = 0.20;
        } else {
          ty = 0.06;
          vyRef = p.y > 0.14 ? -0.38 : -0.16;
          kpX = 9.0; kdX = 5.2;
          kpZ = 9.0; kdZ = 5.2;
        }
      }

      const ex = tx - p.x;
      const ez = tz - p.z;
      const ey = ty - p.y;

      if (Math.abs(ex) < 0.25) intX = clamp(intX + ex * dt, -0.35, 0.35);
      else intX *= 0.92;
      if (Math.abs(ez) < 0.25) intZ = clamp(intZ + ez * dt, -0.35, 0.35);
      else intZ *= 0.92;

      const vxDes = clamp(vxRef + (kpX / kdX) * ex, -1.9, 1.9);
      const vzDes = clamp(vzRef + (kpZ / kdZ) * ez, -1.9, 1.9);
      const vyDes = clamp(vyRef + (kpY / kdY) * ey, -1.5, 1.6);

      // Update kt slightly from vertical velocity error too so zero steady-state vertical error without separate intY
      if (p.y > 0.08 && p.y < 2.90) {
        kt = clamp(kt - 0.12 * (vyDes - v.y) * dt, 14.5, 27.5);
      }

      const axThrustCmd = clamp(kdX * (vxDes - v.x) + 6.5 * intX - wxAcc + cDrag * v.x, -6.4, 6.4);
      const azThrustCmd = clamp(kdZ * (vzDes - v.z) + 8.0 * intZ - wzAcc + cDrag * v.z, -6.4, 6.4);
      const ayDes = clamp(kdY * (vyDes - v.y) + cDrag * v.y, -4.5, 5.5);

      const totalAy = Math.max(2.5, 9.81 + ayDes);

      const axBody = cy * axThrustCmd - sy * azThrustCmd;
      const azBody = sy * axThrustCmd + cy * azThrustCmd;

      const pitchDes = clamp(Math.atan2(axBody, totalAy), -0.55, 0.55);
      const rollDes = clamp(-Math.atan2(azBody, Math.hypot(totalAy, axBody)), -0.55, 0.55);

      const pitch = clamp(pitchDes + pitchTrim + 0.45 * (pitchRef - att.pitch) - 0.05 * rates.pitch, -0.6, 0.6);
      const roll = clamp(rollDes + rollTrim + 0.45 * (rollRef - att.roll) - 0.05 * rates.roll, -0.6, 0.6);

      const aMag = Math.hypot(axThrustCmd, totalAy, azThrustCmd);
      const thrust = clamp(aMag / kt, 0.05, 1.0);

      yawInt = clamp(yawInt - 5.5 * att.yaw * dt, -1.2, 1.2);
      const yawRate = clamp(-4.5 * att.yaw - 0.35 * rates.yaw + yawInt, -2, 2);

      lastThrust = thrust;
      lastRollDes = rollDes;
      lastPitchDes = pitchDes;

      return { thrust, roll, pitch, yawRate };
    },
  };
}

