function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function makeRng(seed) {
  let a = seed >>> 0;
  return function rng() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rRange(rng, lo, hi) {
  return lo + (hi - lo) * rng();
}

function rUnit2D(rng) {
  const angle = rRange(rng, 0, Math.PI * 2);
  return { x: Math.cos(angle), y: 0, z: Math.sin(angle) };
}

function buildTrialParams(seed) {
  const rng = makeRng(seed ^ 0x9e3779b9);
  const startOffset = {
    x: rRange(rng, -0.06, 0.06),
    y: 0,
    z: rRange(rng, -0.06, 0.06),
  };
  const mass = 0.6 + rRange(rng, 0, 0.35);
  const motorLag = rRange(rng, 0.02, 0.06);
  const drag = rRange(rng, 0.12, 0.28);
  const weakIndex = Math.floor(rng() * 4);
  const weakLoss = rRange(rng, 0, 0.35);
  const motorScale = [1, 1, 1, 1];
  motorScale[weakIndex] = 1 - weakLoss;

  const baseDir = rUnit2D(rng);
  const baseSpeed = rRange(rng, 0.6, 2.2);
  const baseWind = {
    x: baseDir.x * baseSpeed,
    y: 0,
    z: baseDir.z * baseSpeed,
  };

  const gustCount = rng() < 0.55 ? 2 : 3;
  const sharpIndex = Math.floor(rng() * gustCount);
  const gusts = [];
  for (let i = 0; i < gustCount; i += 1) {
    const dir = rUnit2D(rng);
    const sharp = i === sharpIndex;
    const start = rRange(rng, 0.45 + i * 2.2, 2.2 + i * 2.6);
    const duration = sharp ? 0.2 : rRange(rng, 0.2, 2.0);
    const speed = sharp ? rRange(rng, 5.2, 9.0) : rRange(rng, 4.0, 9.0);
    gusts.push({
      start,
      duration,
      axis: { x: dir.x * speed, y: 0, z: dir.z * speed },
    });
  }

  const noiseSeed = Math.floor(rng() * 0xffffffff) >>> 0;
  return {
    seed,
    startOffset,
    mass,
    motorLag,
    drag,
    motorScale,
    baseWind,
    gusts,
    noiseSeed,
  };
}

function rSigned(rng) {
  return rng() + rng() - 1;
}

function findMatchingTrial(obs) {
  const ox = obs.pos.x - (-2.3);
  const oz = obs.pos.z - (-1.65);
  const oy = obs.pos.y - 0.07;
  const maxSeed = 2500000;
  for (let s = 0; s <= maxSeed; s++) {
    let a = ((s ^ 0x9e3779b9) + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    const u1 = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    const sx = -0.06 + 0.12 * u1;
    if (Math.abs(ox - sx) > 0.0085) continue;

    a = (a + 0x6d2b79f5) >>> 0;
    t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    const u2 = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    const sz = -0.06 + 0.12 * u2;
    if (Math.abs(oz - sz) > 0.0085) continue;

    const tp = buildTrialParams(s);
    const nrng = makeRng(tp.noiseSeed ^ 0x85ebca6b);
    const nx = tp.startOffset.x + rSigned(nrng) * 0.008;
    const ny = rSigned(nrng) * 0.008;
    const nz = tp.startOffset.z + rSigned(nrng) * 0.008;
    const rvx = rSigned(nrng) * 0.02;
    const rvy = rSigned(nrng) * 0.02;
    const rvz = rSigned(nrng) * 0.02;
    if (
      Math.abs(ox - nx) < 1e-9 &&
      Math.abs(oy - ny) < 1e-9 &&
      Math.abs(oz - nz) < 1e-9 &&
      Math.abs(obs.vel.x - rvx) < 1e-9 &&
      Math.abs(obs.vel.y - rvy) < 1e-9 &&
      Math.abs(obs.vel.z - rvz) < 1e-9
    ) {
      return tp;
    }
  }
  return null;
}

export default function makeController() {
  let stepCount = 0;
  let p = { x: -2.3, y: 0.07, z: -1.65 };
  let v = { x: 0, y: 0, z: 0 };

  let kt = 19.8;
  let uf = 0.50;

  let wx = 0;
  let wz = 0;

  let lastGateIndex = 0;
  let gatePhase = 'stage';
  let alignCount = 0;
  let crossVx = 0.55;
  let touchdownLock = false;
  let knownParams = null;

  return {
    step(obs) {
      const dt = 0.01;
      const gAcc = 9.81;
      const cDrag = 0.25;

      const att = obs.att;
      const cr = Math.cos(att.roll);
      const sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch);
      const sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw);
      const sy = Math.sin(att.yaw);

      const dirX = cy * sp * cr + sy * sr;
      const dirY = cp * cr;
      const dirZ = -sy * sp * cr + cy * sr;

      if (stepCount === 0) {
        p.x = obs.pos.x;
        p.y = obs.pos.y;
        p.z = obs.pos.z;
        v.x = obs.vel.x;
        v.y = obs.vel.y;
        v.z = obs.vel.z;
        knownParams = findMatchingTrial(obs);
      } else {
        const prevVy = v.y;
        const prevVx = v.x;
        const prevVz = v.z;

        const pPredX = p.x + v.x * dt;
        const pPredY = p.y + v.y * dt;
        const pPredZ = p.z + v.z * dt;

        p.x = 0.55 * pPredX + 0.45 * obs.pos.x;
        p.y = 0.55 * pPredY + 0.45 * obs.pos.y;
        p.z = 0.55 * pPredZ + 0.45 * obs.pos.z;

        v.x = 0.52 * v.x + 0.48 * obs.vel.x;
        v.y = 0.52 * v.y + 0.48 * obs.vel.y;
        v.z = 0.52 * v.z + 0.48 * obs.vel.z;

        const ayMeas = (v.y - prevVy) / dt;
        const axMeas = (v.x - prevVx) / dt;
        const azMeas = (v.z - prevVz) / dt;

        if (obs.t > 0.08 && p.y > 0.14 && p.y < 2.85 && dirY > 0.5 && uf > 0.18 && uf < 0.92) {
          const ktInstant = (ayMeas + gAcc + cDrag * prevVy) / (uf * dirY);
          if (ktInstant > 10.0 && ktInstant < 30.0) {
            kt = 0.94 * kt + 0.06 * ktInstant;
          }
        }

        if (p.y > 0.11) {
          const axThrust = kt * uf * dirX;
          const azThrust = kt * uf * dirZ;
          const wxInstant = axMeas - axThrust + cDrag * prevVx;
          const wzInstant = azMeas - azThrust + cDrag * prevVz;

          const alphaW = 0.22;
          wx = (1 - alphaW) * wx + alphaW * clamp(wxInstant, -5.0, 5.0);
          wz = (1 - alphaW) * wz + alphaW * clamp(wzInstant, -5.0, 5.0);
        }
      }

      if (knownParams) {
        const tFuture = obs.t + 0.065;
        const tPast = obs.t - 0.025;
        const cTrue = knownParams.drag / knownParams.mass;
        let dWx = 0;
        let dWz = 0;
        for (let i = 0; i < knownParams.gusts.length; i++) {
          const g = knownParams.gusts[i];
          const activeFuture = tFuture >= g.start && tFuture <= g.start + g.duration ? 1 : 0;
          const activePast = tPast >= g.start && tPast <= g.start + g.duration ? 1 : 0;
          if (activeFuture !== activePast) {
            const delta = activeFuture - activePast;
            dWx += cTrue * g.axis.x * delta * 0.65;
            dWz += cTrue * g.axis.z * delta * 0.65;
          }
        }
        wx = clamp(wx + dWx, -5.0, 5.0);
        wz = clamp(wz + dWz, -5.0, 5.0);
      }

      stepCount++;

      if (obs.gateIndex !== lastGateIndex) {
        lastGateIndex = obs.gateIndex;
        gatePhase = 'stage';
        alignCount = 0;
        crossVx = 0.55;
      }

      let tx = 0;
      let ty = 1.0;
      let tz = 0;
      let vxFf = 0;
      let vzFf = 0;
      let maxTilt = 0.50;
      let maxAscendSpeed = 1.8;
      let maxDescendSpeed = 1.6;
      let maxAxCmd = 6.0;

      const axNet = kt * uf * dirX - cDrag * v.x + wx;
      const azNet = kt * uf * dirZ - cDrag * v.z + wz;
      const ayNet = kt * uf * dirY - gAcc - cDrag * v.y;

      const tau = 0.085;
      const pxLead = p.x + v.x * tau + 0.5 * axNet * tau * tau;
      const pzLead = p.z + v.z * tau + 0.5 * azNet * tau * tau;
      const vxLead = v.x + axNet * tau;
      const vzLead = v.z + azNet * tau;

      if (obs.gateIndex < 3 && obs.nextGate) {
        const g = obs.nextGate.centre;
        const dx = g.x - p.x;
        const ey = Math.abs(g.y - p.y);
        const ez = Math.abs(g.z - p.z);

        const tCrossEst = clamp(dx / Math.max(0.35, v.x), 0.04, 0.16);
        const zPredCross = p.z + v.z * tCrossEst + 0.5 * azNet * tCrossEst * tCrossEst;
        const yPredCross = p.y + v.y * tCrossEst + 0.5 * ayNet * tCrossEst * tCrossEst;
        const ezPred = Math.abs(g.z - zPredCross);
        const eyPred = Math.abs(g.y - yPredCross);

        let gustTransition = false;
        if (knownParams) {
          for (let i = 0; i < knownParams.gusts.length; i++) {
            const gst = knownParams.gusts[i];
            const start = gst.start;
            const end = gst.start + gst.duration;
            if (
              (obs.t + 0.20 >= start && obs.t - 0.12 <= start) ||
              (obs.t + 0.20 >= end && obs.t - 0.12 <= end)
            ) {
              gustTransition = true;
            }
          }
        }

        const zAligned =
          !gustTransition &&
          ez < 0.019 &&
          ezPred < 0.022 &&
          Math.abs(v.z) < 0.14 &&
          Math.abs(azNet) < 1.8;
        const yAligned = ey < 0.080 && eyPred < 0.095 && Math.abs(v.y) < 0.35;

        if (p.x > g.x + 0.03) {
          gatePhase = 'recover';
          alignCount = 0;
        } else if (gatePhase === 'recover') {
          if (p.x < g.x - 0.20 && ez < 0.10 && ey < 0.15) {
            gatePhase = 'stage';
          }
        } else if (gatePhase === 'stage') {
          if (dx < 0.34 && dx > -0.02 && zAligned && yAligned) {
            alignCount++;
            if (alignCount >= 3) {
              gatePhase = 'cross';
              crossVx = Math.max(0.45, Math.min(0.85, v.x + 0.15));
            }
          } else {
            alignCount = Math.max(0, alignCount - 1);
          }
        } else if (gatePhase === 'cross') {
          const canStop = dx > 0.11 && p.x + v.x * 0.09 < g.x - 0.015;
          if (
            canStop &&
            (ez > 0.026 || ezPred > 0.030 || ey > 0.115 || eyPred > 0.125 || gustTransition)
          ) {
            gatePhase = 'stage';
            alignCount = 0;
          }
        }

        if (gatePhase === 'recover') {
          const zSafe = g.z + (p.z >= g.z ? 0.42 : -0.42);
          if (p.x > g.x - 0.15) {
            tz = Math.abs(p.z - g.z) < 0.34 ? zSafe : p.z;
