            ty = g.y;
          } else {
            tx = g.x - 0.25;
            ty = g.y;
            tz = g.z;
          }
        } else if (gatePhase === 'stage') {
          const dynStage = 0.19 + clamp(1.2 * Math.max(0, ez - 0.03), 0, 0.22);
          const stageX = g.x - dynStage;
          tx = stageX;
          ty = obs.t < 0.60 ? Math.min(g.y, 0.25 + 1.45 * obs.t) : g.y;
          tz = obs.t < 0.45 ? -1.65 + (g.z - -1.65) * (obs.t / 0.45) : g.z;
          if (stageX - p.x > 0.35) {
