            return {
              thrust: 0.22,
              roll: 0,
              pitch: 0,
              yawRate: yawCmd,
            };
          }
        }

        if (
          distPad < 0.13 &&
          p.y <= 0.092 &&
          speedHoriz < 0.42 &&
          Math.abs(v.y) < 0.45 &&
          tilt < 0.34
        ) {
          touchdownLock = true;
          const yawCmd = clamp(-4.0 * att.yaw, -2, 2);
          return {
            thrust: 0.22,
            roll: 0,
            pitch: 0,
            yawRate: yawCmd,
          };
        }

        if (distPad > 0.135 || speedHoriz > 0.42) {
          ty = Math.max(0.14, Math.min(0.85, 0.10 + 0.65 * distPad));
          maxDescendSpeed = 1.25;
        } else {
          ty = 0.055;
          maxDescendSpeed = 0.38;
          maxTilt = 0.32;
        }
      }

      const kpY = 7.5;
      const kdY = 4.5;
      const vyTarget = clamp(1.9 * (ty - p.y), -maxDescendSpeed, maxAscendSpeed);
      let ayCmd = kpY * (ty - p.y) + kdY * (0 - v.y) + 2.2 * (vyTarget - v.y);
      if (obs.gateIndex === 3 && p.y < 0.28) {
        ayCmd = Math.max(ayCmd, -2.0);
      }

      const kpX = 5.5;
      const kdX = 3.6;
      const kpZ = 9.0;
      const kdZ = 5.0;

      const exX = clamp(tx - pxLead, -0.50, 0.50);
      const exZ = clamp(tz - pzLead, -0.45, 0.45);

      const axCmd = clamp(kpX * exX + kdX * (vxFf - vxLead), -maxAxCmd, maxAxCmd);
      const azCmd = clamp(kpZ * exZ + kdZ * (vzFf - vzLead), -6.5, 6.5);

      let axDes = axCmd + cDrag * v.x - wx;
      let azDes = azCmd + cDrag * v.z - wz;
      let ayDes = gAcc + ayCmd + cDrag * v.y;
      if (obs.t < 0.60) {
        ayDes = Math.min(ayDes, gAcc + 3.2);
      }
      ayDes = clamp(ayDes, 2.0, 17.5);

      const axBody = cy * axDes - sy * azDes;
      const azBody = sy * axDes + cy * azDes;

      let pitch = clamp(Math.atan2(axBody, ayDes), -maxTilt, maxTilt);
      let roll = clamp(Math.atan2(-azBody * Math.cos(pitch), ayDes), -maxTilt, maxTilt);

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
