      let thrust = clamp(ayDes / (kt * cosTilt), 0.0, obs.t < 0.60 ? 0.78 : 1.0);

      const alphaU = dt / (0.038 + dt);
      uf = (1 - alphaU) * uf + alphaU * thrust;

      const yawRate = clamp(-4.0 * att.yaw, -2, 2);

      return {
        thrust,
        roll,
        pitch,
        yawRate,
      };
    },
  };
}

